#include<bits/stdc++.h>
using namespace std;
const int mod=1e9+7,N=1E5+10;
vector<int>g[N];
int n,m,f[N];
int dfs(int u,int fa){
    if(g[u].size()==1&&g[u][0]==fa){  //当前节点为叶子结点
        f[u]=1;
        return u;
    }
    int minpoint=1e9;
    for(int &x:g[u]){
        if(x==fa)continue;
        minpoint=min(minpoint,dfs(x,u));
    }
    f[u]=f[minpoint]+1;
    return min(u,minpoint);
}
int main(){
    cin>>n;
    for(int i=1;i<n;i++){
        int a,b;
        cin>>a>>b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    dfs(1,0);
    for(int i=1;i<=n;i++)cout<<f[i]<<" ";
    return 0;
}
```

